import java.util.*;import java.util.zip.*;import java.nio.charset.*;import org.objectweb.asm.*;import org.objectweb.asm.tree.*;
public class Inspect{
 static int n;static void ok(boolean b,String s){n++;if(!b)throw new AssertionError(s);}static ClassNode c(ZipFile z,String name)throws Exception{ClassNode c=new ClassNode();new ClassReader(z.getInputStream(z.getEntry(name+".class")).readAllBytes()).accept(c,0);return c;}
 public static void main(String[]args)throws Exception{try(ZipFile z=new ZipFile(args[0])){for(String[]q:new String[][]{{"VanillaCombatMixin","Boxing16","cooldown"},{"BodyPushMixin","BoxingClient16","body"}}){boolean found=false;for(MethodNode m:c(z,"dev/zomboidmelee/mixin/"+q[0]).methods)for(AbstractInsnNode i:m.instructions)if(i instanceof MethodInsnNode a&&a.owner.equals("dev/zomboidmelee/boxing/"+q[1])&&a.name.equals(q[2]))found=true;ok(found,"native hook "+q[0]);}
 for(boolean client:new boolean[]{true,false}){ClassNode e=c(z,"dev/zomboidmelee/boxing/"+(client?"BoxingClientEvents16":"BoxingHitEvents16"));ok(e.visibleAnnotations!=null,"subscriber annotation");ok(e.visibleAnnotations.get(0).values.toString().contains("value")==client,"client rendering code side guard");for(MethodNode m:e.methods){ok(m.visibleAnnotations!=null&&m.visibleAnnotations.get(0).desc.endsWith("SubscribeEvent;"),"listener "+m.name);if(client&&(m.name.equals("input")||m.name.equals("hand")))ok(Arrays.toString((String[])m.visibleAnnotations.get(0).values.get(1)).contains("HIGHEST"),"render/input priority");}}
 for(String type:new String[]{"Boxing16","BoxingClient16","Motion16"})for(MethodNode m:c(z,"dev/zomboidmelee/boxing/"+type).methods)for(AbstractInsnNode i:m.instructions)if(i instanceof MethodInsnNode a)ok(!a.owner.startsWith("yesman/"),"no Epic Fight calls");
 String source=new String(z.getInputStream(z.getEntry("assets/zomboid_global_melee/boxing/epicfight-arm-tracks.json")).readAllBytes(),StandardCharsets.UTF_8);ok(!source.contains("\"Root\"")&&!source.contains("\"Torso\"")&&!source.contains("Thigh"),"no locomotion tracks");}
 System.out.println("NATIVE_BOXING_HOOK_SIDE_DEPENDENCY_CHECKS="+n);}
}
